#!/usr/bin/env python3
"""Materialize v11 and expose exact-document canonical selector coverage."""
from pathlib import Path

root = Path(__file__).resolve().parents[1]
v11 = root / "scripts/_materialize_recoverable_docs_failures_v11.py"
exec(compile(v11.read_text(encoding="utf-8"), str(v11), "exec"), {"__name__": "__main__", "__file__": str(v11)})

gate_path = root / "scripts/run_recovery_contract_gate.py"
gate = gate_path.read_text(encoding="utf-8")
old = '''        try:\n            result = call_docs_tool_payload(\n                "get_docs_context",\n                {\n                    "question": "In docs/ADAPTIVE_TREASURE_CONTRACT.md, summarize meet_type.",\n                    "project_path": str(project),\n                    "mode": "project",\n                    "delivery_strategy": "bounded_direct",\n                    "packet_tokens": 1500,\n                },\n                service,\n            )\n        finally:\n'''
new = '''        try:\n            exact_question = "In docs/ADAPTIVE_TREASURE_CONTRACT.md, summarize meet_type."\n            raw_context = service.get_project_context(\n                str(project), exact_question, mode="project", scope="project"\n            )\n            print("EXACT_PROJECT_DOCS_RESULTS=" + json.dumps([\n                {\n                    "path": row.path,\n                    "source": row.source,\n                    "content": row.content,\n                    "metadata": row.metadata,\n                }\n                for row in (raw_context.project_docs.results if raw_context.project_docs else [])\n            ], indent=2, default=str))\n            print("EXACT_CONTEXT_PACK=" + json.dumps(raw_context.context_pack, indent=2, default=str))\n            debug_requirements = build_requirements(\n                exact_question,\n                required_evidence_paths=("docs/ADAPTIVE_TREASURE_CONTRACT.md",),\n                profile="project_document_answer",\n            )\n            debug_selection = select_evidence(\n                raw_context.context_pack,\n                question=exact_question,\n                config=project_docs_selection_config(800),\n                requirements=debug_requirements,\n            )\n            print("EXACT_SELECTION_DEBUG=" + json.dumps({\n                "status": debug_selection.status,\n                "missing": debug_selection.missing_requirements,\n                "omissions": [vars(row) if hasattr(row, "__dict__") else str(row) for row in debug_selection.omissions],\n                "requirements": [\n                    {\n                        "id": row.requirement_id, "kind": row.kind, "value": row.value,\n                        "mandatory": row.mandatory, "proof_role": row.proof_role,\n                        "source_path": row.source_path,\n                    }\n                    for row in debug_selection.requirements\n                ],\n                "selected": [\n                    {\n                        "id": row.stable_id, "path_or_url": row.path_or_url,\n                        "source_class": row.source_class,\n                        "covered": sorted(row.covered_requirement_ids),\n                        "exact_terms": row.exact_terms,\n                        "symbols": row.symbols,\n                        "text": row.display_text,\n                    }\n                    for row in debug_selection.selected_candidates\n                ],\n                "assignments": [\n                    {\n                        "requirement_id": row.requirement_id,\n                        "evidence_id": row.evidence_id,\n                        "path": row.path,\n                    }\n                    for row in debug_selection.assignments\n                ],\n                "audit": debug_selection.audit_manifest(),\n            }, indent=2, default=str))\n            result = call_docs_tool_payload(\n                "get_docs_context",\n                {\n                    "question": exact_question,\n                    "project_path": str(project),\n                    "mode": "project",\n                    "delivery_strategy": "bounded_direct",\n                    "packet_tokens": 1500,\n                },\n                service,\n            )\n        finally:\n'''
if gate.count(old) != 1:
    raise SystemExit(f"selector diagnostic patch count={gate.count(old)}")
gate_path.write_text(gate.replace(old, new, 1), encoding="utf-8")
